import { useEffect, useState } from "react";
import getTags from "../../services/getTags";
import TagButton from "./TagButton";

const TAG_STATUS = {
  IDLE: "idle",
  LOADING: "loading",
  SUCCESS: "success",
  ERROR: "error",
};

function TagListContent({ status, tags }) {
  if (status === TAG_STATUS.LOADING) {
    return <p>Loading tags...</p>;
  }

  if (tags.length > 0) {
    return <TagButton tags={tags} />;
  }

  if (status === TAG_STATUS.ERROR) {
    return <p>Unable to load tags</p>;
  }

  return <p>Tags list not available</p>;
}

function PopularTags() {
  const [tags, setTags] = useState([]);
  const [status, setStatus] = useState(TAG_STATUS.IDLE);

  useEffect(() => {
    let isMounted = true;

    setStatus(TAG_STATUS.LOADING);

    getTags()
      .then((tagsList) => {
        if (!isMounted) return;

        setTags(tagsList);
        setStatus(TAG_STATUS.SUCCESS);
      })
      .catch((error) => {
        if (!isMounted) return;

        console.error(error);
        setStatus(TAG_STATUS.ERROR);
      });

    return () => {
      isMounted = false;
    };
  }, []);

  return (
    <aside className="col-md-3">
      <div className="sidebar">
        <h6>Popular Tags</h6>
        <div className="tag-list">
          <TagListContent status={status} tags={tags} />
        </div>
      </div>
    </aside>
  );
}

export default PopularTags;

